import unittest
from candidate import get_positive

class TestGetPositive(unittest.TestCase):
    def test_get_positive_normal_case(self):
        self.assertEqual(get_positive([-1, 2, -4, 5, 6]), [2, 5, 6])

    def test_get_positive_mixed_positive_negative(self):
        self.assertEqual(get_positive([5, 3, -5, 2, -3, 3, 9, 0, 123, 1, -10]), [5, 3, 2, 3, 9, 123, 1])

    def test_get_positive_all_positive(self):
        self.assertEqual(get_positive([1, 2, 3, 4]), [1, 2, 3, 4])

    def test_get_positive_all_negative(self):
        self.assertEqual(get_positive([-1, -2, -3]), [])

    def test_get_positive_empty_list(self):
        self.assertEqual(get_positive([]), [])

    def test_get_positive_with_zero(self):
        self.assertEqual(get_positive([-1, 0, 1, 2]), [1, 2])

    def test_get_positive_with_floats(self):
        self.assertEqual(get_positive([-0.1, 0.5, -2.3, 1.7]), [0.5, 1.7])

    def test_get_positive_with_non_numeric_elements(self):
        with self.assertRaises(TypeError):
            get_positive([1, "two", -3])

    def test_get_positive_with_none(self):
        with self.assertRaises(TypeError):
            get_positive([1, None, -2])

    def test_get_positive_single_element_positive(self):
        self.assertEqual(get_positive([42]), [42])

    def test_get_positive_single_element_negative(self):
        self.assertEqual(get_positive([-42]), [])

    def test_get_positive_single_element_zero(self):
        self.assertEqual(get_positive([0]), [])

    def test_get_positive_large_numbers(self):
        self.assertEqual(get_positive([1e18, -1e18, 1]), [1e18, 1])
